import{REWARDS}from'./progression.js?v=balance-8';
import{makeSkyCatalog,BIRD_TYPES,TRAFFIC_TYPES}from'./catalog.js?v=balance-8';
import{groundHeight,random}from'./world.js?v=balance-8';
const B=globalThis.BABYLON,V=B.Vector3;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function segmentDistanceSq(a,b,p){const ab=b.subtract(a),len=ab.lengthSquared();const t=clamp(V.Dot(p.subtract(a),ab)/Math.max(.00001,len),0,1);return V.DistanceSquared(p,a.add(ab.scale(t)));}
export function segmentSegmentDistanceSq(p1,q1,p2,q2){const d1=q1.subtract(p1),d2=q2.subtract(p2),r=p1.subtract(p2),a=V.Dot(d1,d1),e=V.Dot(d2,d2),f=V.Dot(d2,r);let s=0,t=0;if(a<=1e-8&&e<=1e-8)return V.DistanceSquared(p1,p2);if(a<=1e-8)t=clamp(f/e,0,1);else{const c=V.Dot(d1,r);if(e<=1e-8)s=clamp(-c/a,0,1);else{const b=V.Dot(d1,d2),denom=a*e-b*b;s=denom?clamp((b*f-c*e)/denom,0,1):0;t=(b*s+f)/e;if(t<0){t=0;s=clamp(-c/a,0,1);}else if(t>1){t=1;s=clamp((b-c)/a,0,1);}}}return V.DistanceSquared(p1.add(d1.scale(s)),p2.add(d2.scale(t)));}
export class Traffic{
 constructor(scene,damage=null){this.damage=damage;this.scene=scene;this.catalog=makeSkyCatalog(scene);this.items=[];this.encounters=new Map();this.timer=0;this.sequence=0;this.rnd=random(527);this.active=true;}
 reset(s){for(const o of this.items)o.root.dispose(false,false);this.items=[];this.encounters.clear();this.timer=2;this.sequence=0;this.rnd=random(s);this.seed=s;}
 spawnGroup(flight,distance){const rnd=this.rnd,group='sky-'+this.sequence++,bird=rnd()<.56,kind=bird?Math.floor(rnd()*BIRD_TYPES.length):BIRD_TYPES.length+Math.floor(rnd()*TRAFFIC_TYPES.length),source=this.catalog.sources[kind],{f,r}=flight.axes();const horizontal=new V(f.x,0,f.z).normalize(),right=new V(horizontal.z,0,-horizontal.x);const ahead=Math.max(650,flight.speed*5.5)+rnd()*500;const sign=rnd()<.5?-1:1,spread=(rnd()-.5)*230;const projected=flight.position.add(horizontal.scale(ahead)).add(right.scale(spread));projected.y=flight.position.y+(rnd()-.5)*130;projected.y=Math.max(groundHeight(projected.x,projected.z)+55,projected.y);
  const count=bird?5+Math.floor(rnd()*12):1,crossing=bird||rnd()<.63,speed=bird?14+rnd()*11:source.def.speed;const velocity=crossing?right.scale(sign*speed):horizontal.scale(rnd()<.5?-speed:speed*.6);const meetTime=ahead/Math.max(30,flight.speed);projected.subtractInPlace(velocity.scale(Math.min(4,meetTime*.65)));const encounter={id:group,min:Infinity,awarded:false,passed:false,kind:bird?'birds':'aircraft',name:source.def.name};this.encounters.set(group,encounter);
  for(let i=0;i<count;i++){const phase=rnd()*6.28,damageId=this.seed+'/'+group+'/'+i;if(this.damage?.data.traffic.includes(damageId))continue;const model=this.catalog.spawn(kind,null);const wing=i===0?0:(i%2?1:-1);const off=bird?right.scale(wing*Math.ceil(i/2)*3.4).add(horizontal.scale(-Math.ceil(i/2)*4)):V.Zero();model.root.position.copyFrom(projected.add(off));model.root.rotation.y=Math.atan2(velocity.x,velocity.z);this.items.push({...model,id:group,velocity:velocity.clone(),previous:model.root.position.clone(),baseY:model.root.position.y,phase,damageId,age:0,encounter,passed:false,worldSeed:this.sequence});}
 }
 update(dt,flight,distance,canSpawn=true){this.timer-=dt;if(canSpawn&&this.timer<=0){this.spawnGroup(flight,distance);const difficulty=Math.min(1,distance/18000);this.timer=3.1-difficulty*1.5+this.rnd()*1.4;if(this.sequence%7===0)this.timer+=3;}
  for(const o of this.items){o.previous.copyFrom(o.root.position);o.age+=dt;o.root.position.addInPlace(o.velocity.scale(dt));if(o.kind==='bird'){o.root.position.y=o.baseY+Math.sin(o.age*1.3+o.phase)*1.7;for(let j=1;j<o.meshes.length;j++)o.meshes[j].rotation.z=(j===1?-1:1)*Math.sin(o.age*o.def.rate+o.phase)*.56;}else if(o.def.rotor&&o.meshes[1])o.meshes[1].rotation.y+=dt*35;else for(let j=1;j<o.meshes.length;j++)o.meshes[j].rotation.z+=dt*40;}
  this.items=this.items.filter(o=>{const d=V.Distance(o.root.position,flight.position);if(d>Math.max(2600,flight.speed*9)||o.age>75){o.root.dispose(false,false);return false;}return true;});const active=new Set(this.items.map(o=>o.id));for(const id of this.encounters.keys())if(!active.has(id))this.encounters.delete(id);
 }
 check(flight,previous){const{r,f,u}=flight.axes(),probes=[V.Zero(),f.scale(3.8),f.scale(-3.5),r.scale(flight.spec.span*.27),r.scale(-flight.spec.span*.27),r.scale(flight.spec.span*.47),r.scale(-flight.spec.span*.47)];const hits=[];
  for(const o of this.items){const pos=o.root.position,enc=o.encounter;const dist=V.Distance(pos,flight.position);enc.min=Math.min(enc.min,dist);if(dist>100)continue;const yaw=o.root.rotation.y,rf=new V(Math.sin(yaw),0,Math.cos(yaw)),rr=new V(Math.cos(yaw),0,-Math.sin(yaw));let enemy=[{offset:V.Zero(),radius:o.radius}];if(o.kind==='aircraft'&&o.def.airship){enemy.push({offset:rf.scale(o.def.length*.3),radius:6},{offset:rf.scale(-o.def.length*.3),radius:6});}else if(o.kind==='aircraft'){enemy.push({offset:rf.scale(o.def.length*.3),radius:o.radius*.8},{offset:rf.scale(-o.def.length*.3),radius:o.radius*.7});for(const side of[-1,1])for(const t of[.18,.35,.47])enemy.push({offset:rr.scale(o.def.span*side*t),radius:Math.max(1.1,o.def.length*.04)});}
   for(const probe of probes){const a=previous.add(probe).subtract(o.previous),b=flight.position.add(probe).subtract(pos);for(const e of enemy)if(segmentDistanceSq(a,b,e.offset)<(e.radius+1.05)**2){return{collision:o.def.name,impact:{kind:o.kind,target:o,point:pos.add(e.offset)}};}}
  }
  // Score an encounter once, only after its entire group has passed clear of the aircraft.
  for(const enc of this.encounters.values()){if(enc.awarded)continue;const members=this.items.filter(o=>o.id===enc.id);const allBehind=members.length&&members.every(o=>V.Dot(o.root.position.subtract(flight.position),f)<-35);if(allBehind){enc.awarded=true;hits.push({near:enc.min<(enc.kind==='birds'?30:65),value:enc.min<(enc.kind==='birds'?30:65)?enc.kind==='birds'?REWARDS.birdPass:REWARDS.aircraftPass:0,name:enc.name,id:enc.id});}}
  return{passes:hits};
 }
 detachTarget(target){const index=this.items.indexOf(target);if(index<0)return null;this.items.splice(index,1);this.damage?.destroyTraffic(target.damageId);if(!this.items.some(o=>o.id===target.id))this.encounters.delete(target.id);return target;}
 nearest(flight,maxDistance=600){let nearest=null,best=maxDistance;const{f}=flight.axes();for(const o of this.items){const d=V.Distance(o.root.position,flight.position);if(d<best&&V.Dot(o.root.position.subtract(flight.position),f)>0){nearest=o;best=d;}}return nearest?{name:nearest.def.name,distance:best,position:nearest.root.position}:null;}
 rebase(dx,dz){for(const o of this.items){o.root.position.x-=dx;o.root.position.z-=dz;o.previous.x-=dx;o.previous.z-=dz;}}
}
